def load(which):
    """PIL 이미지로 반환: "face" 또는 "body"."""
    from PIL import Image
    data = FACE_B64 if which == "face" else BODY_B64
    return Image.open(io.BytesIO(base64.b64decode(data))).convert("RGBA")
